import{_ as t,o as i,c as e,ag as a}from"./chunks/framework.DEqXEGcv.js";const k=JSON.parse('{"title":"Anti-Pattern Detection Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/anti-patterns.md","filePath":"guides/anti-patterns.md","lastUpdated":1771161798000}'),n={name:"guides/anti-patterns.md"};function r(o,s,p,l,h,d){return i(),e("div",null,[...s[0]||(s[0]=[a('<h1 id="anti-pattern-detection-guide" tabindex="-1">Anti-Pattern Detection Guide <a class="header-anchor" href="#anti-pattern-detection-guide" aria-label="Permalink to &quot;Anti-Pattern Detection Guide&quot;">​</a></h1><p>Hooks in <code>hooks/suppress-*.sh</code> detect and prevent common agent anti-patterns at Write/Edit time. Each hook runs during PreToolUse events.</p><hr><h2 id="_1-custom-retry-logic-suppress-custom-retry-sh" tabindex="-1">1. Custom Retry Logic (<code>suppress-custom-retry.sh</code>) <a class="header-anchor" href="#_1-custom-retry-logic-suppress-custom-retry-sh" aria-label="Permalink to &quot;1. Custom Retry Logic (`suppress-custom-retry.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: Manual retry loops (<code>while retry</code>, <code>for i in range(max_retries)</code>, <code>sleep</code> + retry).</p><p><strong>Why it&#39;s bad</strong>: tenacity is already in project deps. Manual retry loops are error-prone (missing jitter, no backoff, no configurable stop conditions).</p><p><strong>Fix</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tenacity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> retry, stop_after_attempt, wait_exponential</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@retry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">stop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stop_after_attempt(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">wait</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wait_exponential())</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> fetch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; httpx.Response:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>Enforcement</strong>: Advisory (warning only).</p><hr><h2 id="_2-v2-duplicate-files-suppress-v2-files-sh" tabindex="-1">2. V2/Duplicate Files (<code>suppress-v2-files.sh</code>) <a class="header-anchor" href="#_2-v2-duplicate-files-suppress-v2-files-sh" aria-label="Permalink to &quot;2. V2/Duplicate Files (`suppress-v2-files.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: Files named <code>*_v2.*</code>, <code>*_new.*</code>, <code>*_old.*</code>, <code>*_backup.*</code>, <code>*_copy.*</code>, <code>*.bak</code>.</p><p><strong>Why it&#39;s bad</strong>: Duplicates create maintenance burden and divergent implementations. The original file should be refactored instead.</p><p><strong>Fix</strong>: Refactor the original file. Use git branches for experimental changes.</p><p><strong>Enforcement</strong>: <strong>BLOCKING</strong> (prevents file creation).</p><hr><h2 id="_3-hardcoded-provider-strings-suppress-hardcoded-strings-sh" tabindex="-1">3. Hardcoded Provider Strings (<code>suppress-hardcoded-strings.sh</code>) <a class="header-anchor" href="#_3-hardcoded-provider-strings-suppress-hardcoded-strings-sh" aria-label="Permalink to &quot;3. Hardcoded Provider Strings (`suppress-hardcoded-strings.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: <code>provider = &quot;openai&quot;</code>, <code>model = &quot;gpt-4&quot;</code> in non-config files.</p><p><strong>Why it&#39;s bad</strong>: Hardcoded providers make switching impossible without code changes. Config-driven selection enables multi-provider support.</p><p><strong>Fix</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myproject.config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> settings</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">provider </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> registry.get(settings.llm_provider)</span></span></code></pre></div><p><strong>Enforcement</strong>: Advisory (warning only).</p><hr><h2 id="_4-print-statements-suppress-print-statements-sh" tabindex="-1">4. Print Statements (<code>suppress-print-statements.sh</code>) <a class="header-anchor" href="#_4-print-statements-suppress-print-statements-sh" aria-label="Permalink to &quot;4. Print Statements (`suppress-print-statements.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: <code>print()</code> calls in non-CLI source code (2+ occurrences).</p><p><strong>Why it&#39;s bad</strong>: print() produces unstructured output that can&#39;t be filtered, aggregated, or routed. structlog provides structured, context-rich logging.</p><p><strong>Fix</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> structlog</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> structlog.get_logger()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.info(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>Enforcement</strong>: Advisory (warning only). CLI entry points (main.py, cli.py) are excluded.</p><hr><h2 id="_5-god-classes-suppress-isolated-classes-sh" tabindex="-1">5. God Classes (<code>suppress-isolated-classes.sh</code>) <a class="header-anchor" href="#_5-god-classes-suppress-isolated-classes-sh" aria-label="Permalink to &quot;5. God Classes (`suppress-isolated-classes.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: Classes with &gt;15 methods, or 3+ Manager/Handler/Service classes in one file.</p><p><strong>Why it&#39;s bad</strong>: God classes violate single responsibility. Multiple Manager-pattern classes suggest a missing generic registry.</p><p><strong>Fix</strong>: Decompose into smaller classes. Use Protocol/ABC for shared interfaces. Consider a registry pattern for N similar classes.</p><p><strong>Enforcement</strong>: Advisory (warning only).</p><hr><h2 id="_6-direct-http-wrong-library-suppress-direct-http-sh" tabindex="-1">6. Direct HTTP / Wrong Library (<code>suppress-direct-http.sh</code>) <a class="header-anchor" href="#_6-direct-http-wrong-library-suppress-direct-http-sh" aria-label="Permalink to &quot;6. Direct HTTP / Wrong Library (`suppress-direct-http.sh`)&quot;">​</a></h2><p><strong>Pattern</strong>: <code>import requests</code>, <code>import urllib</code>, or custom HTTP wrapper classes without httpx.</p><p><strong>Why it&#39;s bad</strong>: httpx is the project standard (async-capable, modern API). requests is sync-only. urllib is low-level. Custom wrappers duplicate httpx functionality.</p><p><strong>Fix</strong>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Async</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> httpx.AsyncClient() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    response </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.get(url, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><strong>Enforcement</strong>: Advisory (warning only).</p><hr><h2 id="hook-integration" tabindex="-1">Hook Integration <a class="header-anchor" href="#hook-integration" aria-label="Permalink to &quot;Hook Integration&quot;">​</a></h2><p>All hooks receive these environment variables from the dispatcher:</p><ul><li><code>FILE_PATH</code> — absolute path to the file being written/edited</li><li><code>TOOL_CONTENT</code> — full file content (Write)</li><li><code>TOOL_NEW_STRING</code> — replacement text (Edit)</li><li><code>TOOL_NAME</code> — &quot;Write&quot; or &quot;Edit&quot;</li></ul><h3 id="blocking-vs-advisory" tabindex="-1">Blocking vs Advisory <a class="header-anchor" href="#blocking-vs-advisory" aria-label="Permalink to &quot;Blocking vs Advisory&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hook</th><th>Behavior</th><th>Exit Code</th></tr></thead><tbody><tr><td>suppress-v2-files</td><td><strong>Blocking</strong></td><td>2 (with JSON)</td></tr><tr><td>All others</td><td>Advisory</td><td>0 (always)</td></tr></tbody></table><h3 id="consolidated-detector" tabindex="-1">Consolidated Detector <a class="header-anchor" href="#consolidated-detector" aria-label="Permalink to &quot;Consolidated Detector&quot;">​</a></h3><p><code>agent-antipattern-detector.sh</code> combines all patterns into a single hook for performance. The individual <code>suppress-*.sh</code> hooks exist for targeted use or when only specific patterns should be checked.</p>',50)])])}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
